var __main = function () {
var d = [];

// 顶部导航：首页 / 分类 / 排行 / 体育 / 搜索
var curNav = getMyVar('t9_nav', 'home');
navBar(d, curNav);

// ---------- 搜索 ----------
if (curNav === 'search') {
    d.push({
        title: '搜索',
        desc: '搜你想搜...',
        url: "'hiker://search?rule=" + MY_RULE.title + "&s='+input",
        col_type: 'input'
    });
    d.push({ title: '输入片名 / 演员，回车即可搜索', col_type: 'text_center_1' });
    setResult(d);
    return;
}

// ---------- 首页 ----------
if (curNav === 'home') {
    var r = api('/anonymous/v1/home/all/list');
    var data = (r && r.data) || {};

    var blocks = [
        { key: 'homeNewMoviePageData', title: '最新电影' },
        { key: 'homeBroadcastPageData', title: '热播推荐' },
        { key: 'newestTvPageData', title: '最新剧集' },
        { key: 'newestShortTvPageData', title: '最新短剧' },
        { key: 'newestVarietyPageData', title: '最新综艺' },
        { key: 'newestCartoonPageData', title: '最新动漫' },
        { key: 'homeManagerPageData', title: '精选片单' },
        { key: 'homeTrailerPageData', title: '预告片' }
    ];

    for (var b = 0; b < blocks.length; b++) {
        var blk = data[blocks[b].key];
        if (!blk || !blk.list || !blk.list.length) continue;
        sectionTitle(d, blocks[b].title);
        var cs = cards(blk.list);
        for (var c = 0; c < cs.length; c++) d.push(cs[c]);
        d.push({ col_type: 'line_blank' });
    }

    if (d.length <= 6) {
        d.push({ title: '首页数据为空，下拉重试', col_type: 'text_center_1' });
    }

// ---------- 分类 ----------
} else if (curNav === 'cat') {
    var types = getTypes();
    var curType = getMyVar('t9_type1', String(types.length ? types[0].typeId : '1'));

    for (var t = 0; t < types.length; t++) {
        var ta = String(curType) === String(types[t].typeId);
        d.push({
            title: ta ? '✓ ' + types[t].typeName : types[t].typeName,
            col_type: 'scroll_button',
            url: $('#noLoading#').lazyRule((id) => {
                putMyVar('t9_type1', id);
                putMyVar('t9_type', ''); putMyVar('t9_vc', '');
                putMyVar('t9_area', ''); putMyVar('t9_year', ''); putMyVar('t9_lang', '');
                putMyVar('t9_listpage', '1');
                refreshPage(); return 'hiker://empty';
            }, String(types[t].typeId)),
            extra: { backgroundColor: ta ? '#DCF2E2' : '#F2F2F2' }
        });
    }
    d.push({ col_type: 'line_blank' });

    var flt = getFilters(curType);
    filterRow(d, '类型', flt.typeList, getMyVar('t9_type', ''), 'type', true);
    filterRow(d, '地区', flt.districtList, getMyVar('t9_area', ''), 'area');
    filterRow(d, '年份', flt.yearList, getMyVar('t9_year', ''), 'year');
    filterRow(d, '语言', flt.languageList, getMyVar('t9_lang', ''), 'lang');
    filterRow(d, '剧情', flt.plotList, getMyVar('t9_vc', ''), 'v_class');

    // 排序：综合 / 最热 / 高分
    var curSort = getMyVar('t9_sortv', '');
    var sorts = [['', '综合'], ['3_1', '最热'], ['1_2', '高分']];
    for (var si = 0; si < sorts.length; si++) {
        var sa = curSort === sorts[si][0];
        d.push({
            title: sa ? '✓ ' + sorts[si][1] : sorts[si][1],
            col_type: 'scroll_button',
            url: $('#noLoading#').lazyRule((sv) => {
                putMyVar('t9_sortv', sv); putMyVar('t9_listpage', '1');
                refreshPage(); return 'hiker://empty';
            }, sorts[si][0]),
            extra: { backgroundColor: sa ? '#DCF2E2' : '#F2F2F2' }
        });
    }
    d.push({ col_type: 'line_blank' });

    var pg = parseInt(getMyVar('t9_listpage', '1'), 10) || 1;
    var qs = '/anonymous/video/list?type1=' + curType + '&pageNum=' + pg + '&pageSize=24';
    var map = [['type', 'type'], ['area', 'area'], ['year', 'year'], ['lang', 'lang'], ['vc', 'v_class']];
    for (var mi = 0; mi < map.length; mi++) {
        var mv = getMyVar('t9_' + map[mi][0], '');
        if (mv) qs += '&' + map[mi][1] + '=' + encodeURIComponent(mv);
    }
    if (curSort === '3_1') qs += '&sort=3&sortBy=1';
    else if (curSort === '1_2') qs += '&sort=1&sortBy=2';

    var lr = api(qs);
    var ld = (lr && lr.data) || {};
    var cs2 = cards(ld.list || []);
    if (!cs2.length) {
        d.push({ title: '暂无数据，试试换筛选条件', col_type: 'text_center_1' });
    } else {
        for (var m = 0; m < cs2.length; m++) d.push(cs2[m]);
        pager(d, pg, pg < (ld.totalPage || 1));
    }

// ---------- 体育 ----------
} else if (curNav === 'sport') {
    var lv = api('/anonymous/dqSports/getMatchLiving/web');
    var la = (lv && lv.data) || [];
    var live = [];
    for (var q = 0; q < la.length; q++) {
        var ms = Number(la[q].matchStatus);
        if (ms === 2 || ms === 3) live.push(la[q]);
    }
    if (live.length) {
        sectionTitle(d, '正在直播');
        for (var q1 = 0; q1 < live.length && q1 < 8; q1++) {
            var m0 = live[q1];
            d.push({
                title: m0.hostTeamName + '  vs  ' + m0.guestTeamName + '  ' +
                       (m0.hostTeamScore || 0) + ':' + (m0.guestTeamScore || 0),
                desc: m0.leagueName + '  ·  ' + (m0.statusLabel || m0.matchStatusName || ''),
                col_type: 'text_2',
                url: 'hiker://page/sport'
            });
        }
    } else {
        d.push({ title: '当前暂无进行中的直播', col_type: 'text_center_1' });
    }
    d.push({
        title: '⚽ 体育直播专区 · 点击进入',
        desc: '赛事 / 录像 / 集锦',
        col_type: 'text_2',
        url: 'hiker://page/sport'
    });

// ---------- 排行 ----------
} else {
    var rr = api('/anonymous/rank/all');
    var rd = (rr && rr.data) || {};
    var ranks = [
        { key: 'movieRank', title: '电影榜' },
        { key: 'tvRank', title: '剧集榜' },
        { key: 'showRank', title: '综艺榜' },
        { key: 'animRank', title: '动漫榜' },
        { key: 'playletRank', title: '短剧榜' }
    ];
    for (var x = 0; x < ranks.length; x++) {
        var rl = rd[ranks[x].key];
        if (!rl || !rl.length) continue;
        sectionTitle(d, ranks[x].title);
        var rc = cards(rl.slice(0, 12), true);
        for (var y = 0; y < rc.length; y++) d.push(rc[y]);
        d.push({ col_type: 'line_blank' });
    }
    if (d.length <= 6) d.push({ title: '排行数据为空，下拉重试', col_type: 'text_center_1' });
}

setResult(d);
};
__main();

