var __main = function () {
// 搜索词：url##关键词##页码（search_url 里的 ** 被壳子替换后就长这样）
var kw = '', pp = '', pg = 1;
try {
    var u = String(MY_URL || '');
    var parts = u.split('##');
    if (parts.length >= 3) {
        kw = String(parts[1] || '');
        pp = String(parts[2] || '');
    } else if (parts.length === 2) {
        var seg = String(parts[1] || '');
        if (/^\d+$/.test(seg) || seg === 'fypage') pp = seg;
        else kw = seg;
    }
    // 未替换的占位符不算关键词
    if (kw === '**' || kw === 'fypage') kw = '';
    if (/^\d+$/.test(pp)) pg = parseInt(pp, 10) || 1;
} catch (e0) { }
// 兼容 query 形态（老链接 / 内嵌入口）
if (!kw) {
    try {
        var mm = /[?&](?:keyword|wd|s|word)=([^&#]+)/.exec(String(MY_URL || ''));
        if (mm) kw = mm[1];
    } catch (e8) { }
}
if (!kw) { try { kw = String(MY_KEY || ''); } catch (e1) { } }
if (!kw) { try { kw = String(getMyVar('t9_kw', '') || ''); } catch (e2) { } }
if (/%[0-9A-Fa-f]{2}/.test(kw)) { try { kw = decodeURIComponent(kw); } catch (e3) { } }
kw = String(kw).replace(/^\s+|\s+$/g, '');
if (kw) { try { putMyVar('t9_kw', kw); } catch (e4) { } }

if (!kw) {
    d.push({ title: '请输入关键词', col_type: 'text_center_1' });
    setResult(d);
    return;
}

d.push({
    title: '搜索',
    desc: '当前：' + kw,
    url: "'hiker://search?rule=" + MY_RULE.title + "&s='+input",
    col_type: 'input'
});
d.push({ col_type: 'line_blank' });

// 页码优先级：url 里的数字页码 > 换词重置 > 变量里的页码
var lastKw = '';
try { lastKw = String(getMyVar('t9_lastkw', '')); } catch (e5) { }
if (!/^\d+$/.test(pp)) {
    if (lastKw !== kw) {
        pg = 1;
        try { putMyVar('t9_lastkw', kw); } catch (e6) { }
    } else {
        try { pg = parseInt(getMyVar('t9_spage', '1'), 10) || 1; } catch (e7) { }
    }
}
try { putMyVar('t9_spage', String(pg)); } catch (e9) { }

var r = api('/anonymous/video/searchByWordPageable?keyword=' + encodeURIComponent(kw) + '&pageNum=' + pg + '&pageSize=24');
var data = (r && r.data) || {};
var list = data.list || [];

if (!list.length) {
    if (pg <= 1) d.push({ title: '未找到「' + kw + '」相关内容', desc: '换个关键词试试', col_type: 'text_center_1' });
    else d.push({ title: '没有更多了', col_type: 'text_center_1' });
    setResult(d);
    return;
}

if (pg === 1) {
    d.push({
        title: '““””<font color="#666666">找到 ' + (data.totalCount || list.length) + ' 个结果</font>',
        url: 'hiker://empty', col_type: 'text_1'
    });
}

var cs = cards(list);
for (var i = 0; i < cs.length; i++) d.push(cs[i]);

if (pg < (data.totalPage || 1)) {
    d.push({
        title: '下一页 ›（' + pg + '/' + (data.totalPage || 1) + '）',
        col_type: 'text_center_1',
        url: $('#noLoading#').lazyRule((p) => {
            putMyVar('t9_spage', String(parseInt(p, 10) + 1));
            refreshPage(); return 'hiker://empty';
        }, String(pg))
    });
}

setResult(d);
};
__main();

